func Bf(planet1, planet2 string) []string {
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Find indices of the provided planets
	idx1, idx2 := -1, -1
	for i, p := range planets {
		if p == planet1 {
			idx1 = i
		}
		if p == planet2 {
			idx2 = i
		}
	}

	// Return empty slice if either planet is not found
	if idx1 == -1 || idx2 == -1 {
		return []string{}
	}

	// Determine the start and end range
	start, end := idx1, idx2
	if idx1 > idx2 {
		start, end = idx2, idx1
	}

	// Extract planets between the two indices
	var result []string
	for i := start + 1; i < end; i++ {
		result = append(result, planets[i])
	}

	// If no planets are between them, return an empty slice
	if result == nil {
		return []string{}
	}

	return result
}
