#include <iostream>
#include <vector>

using namespace std;

// Recursive function to find the nth number in the sequence
long long customSequenceRecursive(int n) {
    // Base Cases
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // Recursive Step: T(n) = T(n-1) + T(n-2) + T(n-3)
    return customSequenceRecursive(n - 1) + 
           customSequenceRecursive(n - 2) + 
           customSequenceRecursive(n - 3);
}

// Iterative function to find the nth number (Much faster)
long long customSequenceIterative(int n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    long long a = 0;  // T(0)
    long long b = -1; // T(1)
    long long c = -1; // T(2)
    long long next = 0;

    for (int i = 3; i <= n; i++) {
        next = a + b + c;
        a = b;
        b = c;
        c = next;
    }
    return c;
}

int main() {
    int n;
    cout << "Enter the position (n): ";
    cin >> n;

    if (n < 0) {
        cout << "Please enter a non-negative integer." << endl;
    } else {
        // Using iterative for performance, but you can swap to Recursive
        cout << "The number at position " << n << " is: " << customSequenceIterative(n) << endl;

        // Warning: customSequenceRecursive(n) will be very slow for n > 30
    }

    return 0;
}
```

### Explanation

