  // 1. Check for exactly one dot '.'
  // Splitting by '.' should result in an array of exactly 2 elements
  const parts = file_name.split('.');
  if (parts.length !== 2) {
    return 'No';
  }

  const [prefix, suffix] = parts;

  // 2. Check the substring before the dot (prefix)
  // It should not be empty and must start with a Latin letter (a-z, A-Z)
  if (prefix.length === 0 || !/[a-zA-Z]/.test(prefix[0])) {
    return 'No';
  }

  // 3. Check the substring after the dot (suffix)
  // It must be one of: 'txt', 'exe', 'dll'
  const validExtensions = ['txt', 'exe', 'dll'];
  if (!validExtensions.includes(suffix)) {
    return 'No';
  }

  // 4. Check that there are not more than three digits ('0'-'9') in the entire name
  const digits = file_name.match(/\d/g);
  const digitCount = digits ? digits.length : 0;
  if (digitCount > 3) {
    return 'No';
  }

  return 'Yes';
};

// Test cases
console.log(fileNameCheck("example.txt"));    // 'Yes'
console.log(fileNameCheck("1example.dll"));   // 'No' (starts with digit)
console.log(fileNameCheck("test1234.exe"));   // 'No' (too many digits)
console.log(fileNameCheck("my.file.txt"));    // 'No' (too many dots)
console.log(fileNameCheck(".txt"));           // 'No' (empty prefix)
console.log(fileNameCheck("document.pdf"));   // 'No' (invalid extension)
console.log(fileNameCheck("a1b2c3.txt"));     // 'Yes' (exactly 3 digits, starts with letter)
```

```go
import (
	"sort"
)

// Given an array of non-negative integers, return a copy of the given array after sorting,
// you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
// or sort it in descending order if the sum( first index value, last index value) is even.
// 
// Note:
// * don't change the given array.
func SortArray(array []int) []int {
	// Handle empty array case
	if len(array) == 0 {
		return []int{}
	}

	// Create a copy of the array to avoid modifying the original
	res := make([]int, len(array))
	copy(res, array)

	// Calculate the sum of the first and last elements of the original array
	first := array[0]
	last := array[len(array)-1]
	sum := first + last

	if sum%2 != 0 {
		// Sum is odd: Sort in ascending order
		sort.Ints(res)
	} else {
		// Sum is even: Sort in descending order
		sort.Slice(res, func(i, j int) bool {
			return res[i] > res[j]
		})
	}

	return res
}
