```go
// Check if two words have the same characters.
// >>> SameChars('eabcdzzzz', 'dddzzzzzzzddeddabc')
// true
// >>> SameChars('abcd', 'dddddddabc')
// true
// >>> SameChars('dddddddabc', 'abcd')
// true
// >>> SameChars('eabcd', 'dddddddabc')
// false
// >>> SameChars('abcd', 'dddddddabce')
// false
// >>> SameChars('eabcdzzzz', 'dddzzzzzzzddddabc')
// false
func SameChars(s0 string, s1 string) bool {
	// Create maps to act as sets for the unique characters in each string
	set0 := make(map[rune]struct{})
	set1 := make(map[rune]struct{})

	// Populate the first set
	for _, char := range s0 {
		set0[char] = struct{}{}
	}

	// Populate the second set
	for _, char := range s1 {
		set1[char] = struct{}{}
	}

	// If the number of unique characters differs, they cannot have the same set of characters
	if len(set0) != len(set1) {
		return false
	}

	// Check if every character in the first set exists in the second set
	for char := range set0 {
		if _, exists := set1[char]; !exists {
			return false
		}
	}

	return true
}
