/*
  You will be given the name of a class (a string) and a list of extensions.
  The extensions are to be used to load additional classes to the class. The
  strength of the extension is as follows: Let CAP be the number of the uppercase
  letters in the extension's name, and let SM be the number of lowercase letters
  in the extension's name, the strength is given by the fraction CAP - SM.
  You should find the strongest extension and return a string in this
  format: ClassName.StrongestExtensionName.
  If there are two or more extensions with the same strength, you should
  choose the one that comes first in the list.
*/
const strongestExtension = (class_name, extensions) => {
  let maxStrength = -Infinity;
  let strongestExt = "";

  for (const ext of extensions) {
    let caps = 0;
    let sms = 0;

    // Iterate through each character of the extension to count case
    for (let i = 0; i < ext.length; i++) {
      const char = ext[i];
      if (char >= 'A' && char <= 'Z') {
        caps++;
      } else if (char >= 'a' && char <= 'z') {
        sms++;
      }
    }

    const strength = caps - sms;

    // We use strictly greater than (>) to ensure that if strengths are equal,
    // the one that appeared first in the list is kept.
    if (strength > maxStrength) {
      maxStrength = strength;
      strongestExt = ext;
    }
  }

  return `${class_name}.${strongestExt}`;
};

// Test cases
console.log(strongestExtension('Slices', ['SErviNGSliCes', 'Cheese', 'StuFfed'])); // 'Slices.SErviNGSliCes'
console.log(strongestExtension('my_class', ['AA', 'Be', 'CC'])); // 'my_class.AA'
```

```javascript
/*
  Write a function that takes a message, and encodes in such a 
  way that it swaps case of all letters, replaces all vowels in 
  the message with the letter that appears 2 places ahead of that 
  vowel in the english alphabet. 
  Assume only letters. 

  Examples:
  >>> encode('test')
  'TGST'
  >>> encode('This is a message')
  'tHKS KS C MGSSCGG'
  */
const encode = (message) => {
  const vowels = 'aeiouAEIOU';

  return message
    .split('')
    .map((char) => {
      // 1. Swap the case of the character
      let swapped = char === char.toUpperCase() 
        ? char.toLowerCase() 
        : char.toUpperCase();

      // 2. If the original character was a vowel, 
      // shift the swapped character 2 places forward in the alphabet
      if (vowels.includes(char)) {
        swapped = String.fromCharCode(swapped.charCodeAt(0) + 2);
      }

      return swapped;
    })
    .join('');
};

// Test cases
console.log(encode('test'));               // Output: 'TGST'
console.log(encode('This is a message'));  // Output: 'tHKS KS C MGSSCGG'
