// GetRow finds all occurrences of integer x in a 2D slice (nested lists).
// It returns a list of coordinates (row, col) where x is found.
// The results are sorted by row in ascending order and by column in descending order.
func GetRow(lst [][]int, x int) [][2]int {
	var result [][2]int

	// We iterate through the rows in ascending order (0 to len-1).
	for i := 0; i < len(lst); i++ {
		// To satisfy the requirement that columns within a row are sorted in descending order,
		// we iterate through the columns of the current row backwards.
		for j := len(lst[i]) - 1; j >= 0; j-- {
			if lst[i][j] == x {
				result = append(result, [2]int{i, j})
			}
		}
	}

	return result
}

// Note: While the "sort" package was imported in the prompt, 
