    int max_strength = INT_MIN;
    string strongest_ext = "";

    for (const string& ext : extensions) {
        int upper_count = 0;
        int lower_count = 0;

        // Calculate the number of uppercase and lowercase letters in the current extension
        for (char c : ext) {
            if (isupper(c)) {
                upper_count++;
            } else if (islower(c)) {
                lower_count++;
            }
        }

        // Strength is defined as CAP - SM
        int current_strength = upper_count - lower_count;

        // We update the strongest extension if the current strength is strictly greater.
        // This ensures that if two extensions have the same strength, the one that 
        // appeared first in the vector is kept.
        if (current_strength > max_strength) {
            max_strength = current_strength;
            strongest_ext = ext;
        }
    }

    // Return the result in the format ClassName.StrongestExtensionName
    return class_name + "." + strongest_ext;
}
