func Bf(planet1, planet2 string) []string {
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Find the index of planet1
	idx1 := -1
	for i, p := range planets {
		if p == planet1 {
			idx1 = i
			break
		}
	}

	// Find the index of planet2
	idx2 := -1
	for i, p := range planets {
		if p == planet2 {
			idx2 = i
			break
		}
	}

	// If either planet is not found, return an empty slice
	if idx1 == -1 || idx2 == -1 {
		return []string{}
	}

	// Determine the start and end indices for the range
	start := idx1
	end := idx2
	if idx1 > idx2 {
		start = idx2
		end = idx1
	}

	// The range is between the two planets, so we start at start+1 
	// and end at end (exclusive in Go slicing)
	if start+1 >= end {
		return []string{}
	}

	// Return the slice of planets between the two indices
	return planets[start+1 : end]
}
